/**
* Lightning Component
* A high-performance WebGL-powered electric discharge effect.
* Features customizable hue, intensity, speed, and size via GLSL shaders.
*/

import React, { useRef, useEffect } from 'react';

export interface LightningProps {
/** Hue of the lightning in degrees (0-360) */
hue?: number;
/** Horizontal offset of the effect */
xOffset?: number;
/** Animation speed multiplier */
speed?: number;
/** Visual intensity/brightness multiplier */
intensity?: number;
/** Scale/complexity of the noise pattern */
size?: number;
/** Optional className for the canvas container */
className?: string;
}

export const Lightning: React.FC<LightningProps> = ({
hue = 230,
xOffset = 0,
speed = 1,
intensity = 1,
size = 1,
className = ""
}) => {
const canvasRef = useRef<HTMLCanvasElement>(null);

useEffect(() => {
const canvas = canvasRef.current;
if (!canvas) return;

const gl = canvas.getContext('webgl', { antialias: true, alpha: true });
if (!gl) {
console.error('WebGL not supported');
return;
}

const resizeCanvas = () => {
const displayWidth = canvas.clientWidth;
const displayHeight = canvas.clientHeight;
if (canvas.width !== displayWidth || canvas.height !== displayHeight) {
canvas.width = displayWidth;
canvas.height = displayHeight;
gl.viewport(0, 0, canvas.width, canvas.height);
}
};

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const vertexShaderSource = `
attribute vec2 aPosition;
void main() {
gl_Position = vec4(aPosition, 0.0, 1.0);
}
`;

const fragmentShaderSource = `
precision mediump float;
uniform vec2 iResolution;
uniform float iTime;
uniform float uHue;
uniform float uXOffset;
uniform float uSpeed;
uniform float uIntensity;
uniform float uSize;

#define OCTAVE_COUNT 10

vec3 hsv2rgb(vec3 c) {
vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0,4.0,2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
return c.z * mix(vec3(1.0), rgb, c.y);
}

float hash11(float p) {
p = fract(p * .1031);
p *= p + 33.33;
p *= p + p;
return fract(p);
}

float hash12(vec2 p) {
vec3 p3 = fract(vec3(p.xyx) * .1031);
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}

mat2 rotate2d(float theta) {
float c = cos(theta);
float s = sin(theta);
return mat2(c, -s, s, c);
}

float noise(vec2 p) {
vec2 ip = floor(p);
vec2 fp = fract(p);
float a = hash12(ip);
float b = hash12(ip + vec2(1.0, 0.0));
float c = hash12(ip + vec2(0.0, 1.0));
float d = hash12(ip + vec2(1.0, 1.0));

vec2 t = smoothstep(0.0, 1.0, fp);
return mix(mix(a, b, t.x), mix(c, d, t.x), t.y);
}

float fbm(vec2 p) {
float value = 0.0;
float amplitude = 0.5;
for (int i = 0; i < OCTAVE_COUNT; ++i) {
value += amplitude * noise(p);
p *= rotate2d(0.45);
p *= 2.0;
amplitude *= 0.5;
}
return value;
}

void main() {
vec2 uv = gl_FragCoord.xy / iResolution.xy;
uv = 2.0 * uv - 1.0;
uv.x *= iResolution.x / iResolution.y;
uv.x += uXOffset;

float time = iTime * uSpeed;

// Warp UV coordinates with FBM for lightning shape
