roadColor: number;
islandColor: number;
background: number;
shoulderLines: number;
brokenLines: number;
leftCars: number[];
rightCars: number[];
sticks: number;
};
}

export interface HyperspeedProps {
effectOptions?: HyperspeedOptions;
className?: string;
}

const DEFAULT_OPTIONS: HyperspeedOptions = {
onSpeedUp: () => { },
onSlowDown: () => { },
distortion: 'turbulentDistortion',
length: 400,
roadWidth: 10,
islandWidth: 2,
