.scene>img{object-fit:cover;user-select:none;-webkit-user-drag:none}
.rings path{fill:none;stroke:var(--ring);stroke-width:1;stroke-linecap:butt}
.title{position:absolute;left:0;width:calc(635 * 2 * var(--sc));top:calc(378 * var(--sc));
  font:400 calc(46 * var(--sc))/1 var(--sans);font-kerning:none;letter-spacing:-0.01em;color:var(--ink);text-align:center;white-space:nowrap}
.title span{display:inline-block;margin-left:calc(var(--k,0) * var(--sc))}
.ui{position:absolute;inset:0;pointer-events:none}
.ui>*{pointer-events:auto}
.copy{position:absolute;font:400 calc(14 * var(--u))/calc(17.5 * var(--u)) var(--mono);letter-spacing:-0.025em;color:var(--ink);text-transform:uppercase;white-space:nowrap}
.copy--tl{left:calc(34.5 * var(--u));top:calc(46.6 * var(--u))}
.copy--tr{right:calc(45 * var(--u));top:calc(39 * var(--u));text-align:right}
.copy--bl{left:calc(34.5 * var(--u));bottom:calc(39.5 * var(--u))}
.copy--br{right:calc(45 * var(--u));bottom:calc(39.5 * var(--u));text-align:right}
.nav{position:absolute;top:calc(29.5 * var(--u));left:calc(50% - 5 * var(--u));transform:translateX(-50%);
  width:calc(300.5 * var(--u));height:calc(53.7 * var(--u));background:var(--panel);display:flex;align-items:center;justify-content:space-between;
  padding:0 calc(15 * var(--u)) 0 calc(9 * var(--u))}
.logo{display:block;color:var(--ink);text-decoration:none;font:700 calc(39 * var(--u))/1 var(--sans);letter-spacing:-0.01em;transform:translateY(calc(-5 * var(--u)))}
.menu{position:relative;width:calc(17 * var(--u));height:calc(8.3 * var(--u));background:none;border:0;cursor:pointer;transform:translateY(calc(-0.5 * var(--u)))}
.menu::before,.menu::after{content:"";position:absolute;left:0;right:0;height:max(1px,calc(1 * var(--u)));background:var(--ink)}
.menu::before{top:0}.menu::after{bottom:0}
.ctas{position:absolute;left:calc(35 * var(--u));bottom:calc(98 * var(--u));display:flex;flex-direction:column;gap:calc(9 * var(--u))}
.btn{display:flex;align-items:center;justify-content:center;width:calc(142.4 * var(--u));height:calc(45 * var(--u));background:var(--panel);color:var(--ink);text-decoration:none;
  font:400 calc(14 * var(--u))/1 var(--mono);letter-spacing:-0.025em;text-transform:uppercase;white-space:nowrap;padding-top:calc(0.5 * 2 * var(--u));transition:background .2s,color .2s}
.btn:hover{background:var(--ink);color:var(--panel)}
a:focus-visible,button:focus-visible{outline:2px solid #fff;outline-offset:3px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@media (orientation:portrait) and (min-width:561px){ :root{ --u:clamp(.72px, calc(var(--vw) / 860), 1.6px); } }
@media (max-width:560px){
  :root{ --u:clamp(.72px, calc(var(--vw) / 470), 1px); }
  .nav{left:calc(20 * var(--u));right:calc(20 * var(--u));width:auto;transform:none;top:calc(20 * var(--u))}
  .copy--tl{left:calc(20 * var(--u));top:calc(96 * var(--u))}
  .copy--tr{right:calc(20 * var(--u));top:calc(96 * var(--u))}
  .copy--bl{left:calc(20 * var(--u));bottom:calc(24 * var(--u))}
  .ctas{left:calc(20 * var(--u));bottom:calc(76 * var(--u))}
  .copy--br{right:calc(20 * var(--u));bottom:calc(24 * var(--u))}
}
