.px-intro .title span{translate:0 105%}
.px-intro .ln{overflow:hidden}
.px-intro .ln>span{translate:0 105%}
.px-intro .nav{clip-path:inset(0 50% 0 50%)}
.px-intro .logo,.px-intro .menu{opacity:0}
